(()=>{const rows=[["Analytical integrity", ["Primary", "Primary", "Shared", "Shared", "Shared", "Shared"], "Maintain analytical results and process integrity as mobile phase is recycled.", "Retention time, peak area, peak shape and system suitability against agreed acceptance criteria.", "Analytical comparison, injection records and approved method assessment.", "quality", "192 injections across two 96-injection sequences; measured study evidence, separate from the operating model.", "Analytical acceptance and controlled change; no certification inferred."], ["Analyst capacity", ["Primary", "Shared", "Shared", "Shared", "Shared", "Primary"], "Reduce repetitive preparation and handling so analysts can spend more time on higher-value work.", "Preparation hours and handling events per accepted analytical workload; time demonstrably redeployed.", "Matched-workload time study and laboratory schedules. Released time is not automatically a cash saving.", "quality", "30% less preparation/handling time: example assumption. Absolute hours require a measured baseline.", "Capacity and process-performance review; retain time-study evidence."], ["Material cost", ["Shared", "Shared", "Shared", "Primary", "Primary", "Primary"], "Reduce fresh-solvent demand and the purchasing spend associated with it.", "Net fresh litres avoided × actual ingredient cost; subtract implementation and ongoing costs for ROI.", "Fresh-input balance, recipe, invoices and operating costs. Count the shared saving once.", "procurement", "€552,960 gross material cost avoided over three years at €100/L.", "ISO 14051 material-flow cost accounting; subtract implementation and ongoing costs for ROI."], ["Waste & circularity", ["Shared", "Shared", "Primary", "Shared", "Shared", "Primary"], "Keep suitable mobile phase in productive use and prevent waste at its source.", "Fresh input and hazardous waste per accepted workload, including top-ups, cleaning and final disposal.", "Material balance and waste-transfer records. Recycled throughput is not net waste prevention.", "sustainability", "5,529.6 L net waste prevented over three years; approximately 5.53 t at 1 kg/L.", "ISO 14001 environmental objectives and ISO 14051 material balances."], ["Carbon metrics", ["Shared", "Shared", "Primary", "Shared", "Shared", "Primary"], "Connect material and waste reductions to the relevant emissions categories.", "Verified fresh litres avoided × production factor, plus net waste avoided × treatment factor.", "Applicable emission factors and reporting boundaries. Avoid counting the same reduction in multiple categories.", "sustainability", "29.09 t CO₂e over three years: production 20.40 t + treatment 8.68 t (rounded).", "GHG Protocol Scope 3 Categories 1 and 5, subject to boundary; ISO 14064-1 organisational accounting."], ["Price & supply exposure", ["Shared", "Shared", "Shared", "Primary", "Primary", "Primary"], "Lower the volume exposed to price changes and extend the useful coverage of existing stocks.", "Ingredient demand, usable stock days, lead times and solvent-related testing interruptions.", "Inventory, supplier terms, purchase orders and shortage logs. Reduced consumption does not eliminate supply risk.", "supply-chain", "Fresh requirement falls from 6,912 L to 1,382.4 L over three years; 5× theoretical coverage at unchanged usable stock.", "Supply continuity metric; validate ingredient demand, expiry and stock policy."], ["Traceable improvement", ["Primary", "Primary", "Primary", "Shared", "Shared", "Primary"], "Give the investment decision a shared, reviewable evidence base.", "Approved scope, source records, baseline, measured outcomes and accountable benefit owners.", "Audit extracts, change control and site review. Agree actual responsibilities within your organisation.", "research", "One baseline; three-year cumulative figures; seven value areas and six stakeholder groups.", "ISO 14001 performance evidence, ISO 14051 cost/flow records and ISO 14064-1 GHG data quality."]];const panel=document.getElementById('value-detail');function show(i){const r=rows[i];panel.innerHTML='<h3>'+r[0]+'</h3><p>'+r[2]+'</p><dl><dt>Figure / metric</dt><dd>'+r[6]+'</dd><dt>Alignment</dt><dd>'+r[7]+'</dd><dt>Measure</dt><dd>'+r[3]+'</dd><dt>Evidence</dt><dd>'+r[4]+'</dd></dl><button type="button" class="text-button" id="value-evidence-link">Explore this evidence →</button>';document.getElementById('value-evidence-link').onclick=()=>{document.getElementById('nav-'+r[5]).click();document.getElementById('nav-'+r[5]).scrollIntoView({block:'center'});};document.querySelectorAll('[data-value-row]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.valueRow)===i)));}document.querySelectorAll('[data-value-row]').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.valueRow))));show(0);})();